#!/bin/sh
#
# This script is used to check that the ABI of the libraries in the "lib"
# subdirectory is compatible with the ABI descriptions in the given directory,
# which are normally generated by generate_all.sh from the build of the first
# stable release of the current branch.
#
# Libraries without the corresponding ABI description, e.g. new libraries
# added after the first stable release, are skipped, but at least one library
# must be checked, as otherwise something is clearly wrong, e.g. the ABI
# descriptions are for the libraries with different names.

if [ $# -ne 1 ]; then
    echo "Usage: $0 <directory-with-abi-descriptions>" >&2
    exit 2
fi

abidir="$1"

libraries=$(ls -1 lib/*.so)

if [ -z "$libraries" ]; then
    echo 'Please run the script from the build directory and build the libraries first.' >&2
    exit 1
fi

rc=0
checked=0
for l in $libraries; do
    name=$(basename $l .so)
    echo -n "Checking ${name}... "
    if [ ! -f "${abidir}/${name}.abi" ]; then
        echo 'skipped (no ABI description)'
        continue
    fi

    checked=$((checked + 1))
    abidiff "${abidir}/${name}.abi" $l
    case $? in
        0)
            echo 'ok'
            ;;

        4)
            echo "*** ABI changes detected in ${name} ***"
            ;;

        *)
            echo "!!! INCOMPATIBLE ABI changes detected in ${name} !!!"
            rc=1
            ;;
    esac
done

if [ $checked -eq 0 ]; then
    echo "No ABI descriptions for any of the libraries found in ${abidir}." >&2
    exit 1
fi

exit $rc
